/**
 * The current user's deliveries, newest first: the simulated phone panel uses `channel=sms&channel=phone`.
 * @summary List My Messages
 */
export const listMyMessagesQueryLimitDefault = 50;
export const listMyMessagesQueryLimitMax = 100;

export const listMyMessagesQueryOffsetDefault = 0;
export const listMyMessagesQueryOffsetMin = 0;
export const listMyMessagesQueryOffsetMax = 1000000;



export const ListMyMessagesQueryParams = zod.object({
  "limit": zod.int().min(1).max(listMyMessagesQueryLimitMax).default(listMyMessagesQueryLimitDefault),
  "offset": zod.int().min(listMyMessagesQueryOffsetMin).max(listMyMessagesQueryOffsetMax).default(listMyMessagesQueryOffsetDefault),
  "channel": zod.union([zod.array(zod.enum(['email', 'sms', 'phone', 'ui'])),zod.null()]).optional()
})

export const ListMyMessagesResponseItem = zod.object({
  "id": zod.uuid(),
  "alert_id": zod.uuid(),
  "user_id": zod.uuid(),
  "channel": zod.enum(['email', 'sms', 'phone', 'ui']),
  "status": zod.enum(['pending', 'sent', 'failed']),
  "attempts": zod.int(),
  "last_error": zod.union([zod.string(),zod.null()]),
  "message": zod.string().describe('What was sent, as rendered for the channel'),
  "created_at": zod.iso.datetime({"offset":true}),
  "sent_at": zod.union([zod.iso.datetime({"offset":true}),zod.null()])
})
export const ListMyMessagesResponse = zod.array(ListMyMessagesResponseItem)

